    def myAtoi(self, s: str) -> int:
        s= s.strip(" ")
        if len(s) == 0:return 0
        s = list(s)
        sign = 1

        if s[0] == "-":
            sign = -1
            s.pop(0) # Removing the sign from the first term 
        elif s[0] == "+":
            sign = 1
            s.pop(0)
        else:
            pass

        if len(s) > 2 and not s[0].isdigit():
            return 0
        _ = "0"

        for i in s:
            if i.isdigit():
                _+=i
            else:
                break

        return_val = int(_) * sign

        if return_val < -2147483648:
            return -2147483648

        elif return_val > 2147483647:
            return 2147483647

        else:
            return return_val
