// class Solution:
    def hasCycle(self, head: Optional[ListNode]) -> bool:
        # if linkedlist empty
        if not head:
            return False

        # fast, slow nodes
        fast = slow = head

        # counter for fast and slow
        cnt = 0

        # while before end of linkedlist
        while fast:
            # advance fast
            fast = fast.next

            # every other loop
            if cnt % 2:
                # advance slow
                slow = slow.next

            # if fast and slow point to the same node, we have a loop
            if fast is slow:
                return True

            # increment cnt
            cnt += 1

        return False
