    def binarysrc(self,arr,k):
        l=0
        r=len(arr)-1
        while l<=r:
            m=(l+r)//2
            if arr[m]==k:
                return m
            elif k>arr[m]:
                l=m+1
            else:
                r=m-1
        else:
            return -1  
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        for i in range(len(matrix)):
            if target>=matrix[i][0] and target<=matrix[i][-1]:
                if self.binarysrc(matrix[i],target)!=-1:
                    return True
        return False
