    def wiggleMaxLength(self, nums: List[int]) -> int:
        if not nums:
            return 0
        less = [1]*len(nums)
        more = [1]*len(nums)
        res_l = 1
        res_m = 1

        for i in range(1,len(nums)):
            for j in range(i):
                if nums[i] > nums[j] and more[i] < less[j]+1:
                    more[i] = less[j]+1
                    res_m = more[i]

                elif nums[i] < nums[j] and less[i] < more[j]+1:
                    less[i] = more[j]+1
                    res_l = less[i]
        return max(res_l,res_m)
