    def pathSum(self, root: TreeNode, targetSum: int) -> int:
        cnt = 0
        if not root:
            return cnt

        def counter(n: TreeNode, s=0):
            nonlocal cnt
            if not n:
                return
            s += n.val
            if s == targetSum:
                cnt += 1
            counter(n.left, s)
            counter(n.right, s)

        def dfs(n: TreeNode):
            if not n:
                return
            counter(n)
            dfs(n.left)
            dfs(n.right)

        dfs(root)
        return cnt
