    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:

        wordset = set(words)

        @cache
        def f(word,i):
            if i >= len(word):
                return True
            j = i+1
            while j <= len(word):
                if word[i:j] in wordset and j-i != len(word) and f(word,j):
                    return True
                j += 1
            return False

        return [word for word in words if any(word) and f(word,0)]
