    def makesquare(self, matchsticks) -> bool:
        total_circumference = sum(matchsticks)
        side = total_circumference/4

        if int(side) != side:
            return False

        matchsticks.sort()

        paths = [0]*4
        h = {}

        if matchsticks[-1] > side:
            return False

        def r():
            if not matchsticks:
                return True

            num = matchsticks.pop()

            ret = False
            for x in range(4):
                if paths[x] + num <= side:
                    paths[x] += num
                    ret |= r()
                    if ret:
                        return True
                    paths[x] -= num
                    if not paths[x]:
                        break

            matchsticks.append(num)
            return ret
        return r()
