    def findUnsortedSubarray(self, nums: List[int]) -> int:
        sortednums = sorted(nums)
        if sortednums == nums:
            return 0
        start = 0
        end = len(nums)-1
        for i in range(len(nums)):
            if nums[i]!=sortednums[i]:
                start = i
                break
        for i in range(len(nums)-1,0,-1):
            if nums[i]!=sortednums[i]:
                end = i
                break
        return len(nums[start:end+1])
