        def hii(temp,d):

            if d==2 and temp:
                x=TreeNode(v)
                y=TreeNode(v)
                x.left=temp.left
                y.right=temp.right
                temp.left=x
                temp.right=y
                return root
            else:
                if temp:
                    hii(temp.left,d-1)
                    hii(temp.right,d-1)
            return root

        if d==1:
            x=TreeNode(v)
            x.left=root
            return x

        return hii(temp,d)
