    def findSecondMinimumValue(self, root: TreeNode) -> int:
        if not root.left:
            return -1

        if not root:
            return -1
        left=self.findSecondMinimumValue(root.left)
        right = self.findSecondMinimumValue(root.right)
        if root.right.val>root.val:
            if left==-1:
                return root.right.val
            else:
