    def shortestToChar(self, S: str, C: str) -> List[int]:
        l=[]
        x=[]
        for i in range(len(S)):
            if(S[i]==C):
                l.append(i)
        a=l[0]
        b=l[len(l)-1]
        k=0
        for i in range(len(S)):
            if(i<a):
                x.append(a-i)
            elif(i>b):
                x.append(i-b)
            else:
                if(i==l[k]):
                    x.append(0)
                    if(k<len(l)-1):
                        k+=1
                        continue
                else:
                    x.append(min(i-l[k-1],l[k]-i))
        return x
