// class Solution:
    def numFactoredBinaryTrees(self, arr: List[int]) -> int:

        arr.sort()

        memo={}
        memo[arr[0]] = 1

        for i in range(1, len(arr)):
            count = 1
            for j in range(0, i):
                if arr[i]/arr[j] in memo:
                    count+=memo[arr[j]]*memo[arr[i]/arr[j]]
            memo[arr[i]] = count
        return sum(memo.values()) % (10**9+7)
